  Write-Error "Falha ao localizar o arquivo"
}

{
  "services": {
    "db": {
      "image": "postgres:17",
      "healthcheck": {
        "test": ["CMD-SHELL", "pg_isready -U app"],
        "interval": "5s",
        "timeout": "3s",
        "retries": 10
      },
      "volumes": ["dbdata:/var/lib/postgresql/data"],
      "networks": ["appnet"]
    },
    "web": {
      "image": "exemplo/web:1.0",
      "depends_on": {"db": {"condition": "service_healthy"}},
      "ports": ["8080:80"],
      "networks": ["appnet"]
    }
  },
  "volumes": {"dbdata": {}},
  "networks": {"appnet": {}}
}
